   335  otError Ip6::SendDatagram(Message &aMessage, MessageInfo &aMessageInfo, IpProto aIpProto)
   336  {
   337      otError error = OT_ERROR_NONE;
   338      Header header;
   339      uint16_t payloadLength = aMessage.GetLength();
   340      uint16_t checksum;
   341      const NetifUnicastAddress *source;
   342
   343      header.Init();
   344      header.SetPayloadLength(payloadLength);
   345      header.SetNextHeader(aIpProto);
   346      header.SetHopLimit(aMessageInfo.mHopLimit ? aMessageInfo.mHopLimit : static_cast<uint8_t>(kDefaultHopLimit));
   347
   348      if (aMessageInfo.GetSockAddr().IsUnspecified() ||
   349          aMessageInfo.GetSockAddr().IsMulticast())
   350      {
   351          VerifyOrExit((source = SelectSourceAddress(aMessageInfo)) != NULL,
   352                       error = OT_ERROR_INVALID_SOURCE_ADDRESS);
   353          header.SetSource(source->GetAddress());
   354      }
   355      else
   356      {
   357          header.SetSource(aMessageInfo.GetSockAddr());
   358      }
   359
   360      header.SetDestination(aMessageInfo.GetPeerAddr());
   361
   362      if (header.GetDestination().IsLinkLocal() || header.GetDestination().IsLinkLocalMulticast())
   363      {
   364          VerifyOrExit(aMessageInfo.GetInterfaceId() != 0, error = OT_ERROR_DROP);
   365      }
   366
   367      if (aMessageInfo.GetPeerAddr().IsRealmLocalMulticast())
   368      {
   369          SuccessOrExit(error = AddMplOption(aMessage, header));
   370      }
   371
   372      SuccessOrExit(error = aMessage.Prepend(&header, sizeof(header)));
   373
   374      if (aMessageInfo.GetPeerAddr().IsMulticast() &&
   375          aMessageInfo.GetPeerAddr().GetScope() > Address::kRealmLocalScope)
   376      {
   377          SuccessOrExit(error = AddTunneledMplOption(aMessage, header, aMessageInfo));
   378      }
   379
   380      // compute checksum
   381      checksum = ComputePseudoheaderChecksum(header.GetSource(), header.GetDestination(),
   382                                             payloadLength, aIpProto);
   383
   384      switch (aIpProto)
   385      {
   386      case kProtoUdp:
   387          SuccessOrExit(error = mUdp.UpdateChecksum(aMessage, checksum));
   388          break;
   389
   390      case kProtoIcmp6:
   391          SuccessOrExit(error = mIcmp.UpdateChecksum(aMessage, checksum));
   392          break;
   393
   394      default:
   395          break;
   396      }
   397
   398  exit:
   399
   400      if (error == OT_ERROR_NONE)
   401      {
   402          aMessage.SetInterfaceId(aMessageInfo.GetInterfaceId());
   403          EnqueueDatagram(aMessage);
   404      }
   405
   406      return error;
   407  }
